using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "OnSoulHeatHitValueEffects", menuName = "Data/Battle/Effects/Sothis/OnSoulHeatHitValue Effect")]
public class OnSoulHeatHitValueEffects : Effect
{
	[Header("Soul Heat")]
	[SerializeField]
	protected SoulHeat soulHeat;

	[SerializeField]
	protected int soulHeatToTrigger;

	public virtual void OnSoulHeatHitValue(PlayerEffects playerEffects)
	{
		if (soulHeat.SoulHeatCounter >= soulHeatToTrigger)
		{
			playerEffects.IsEffectActive(this);
			ActivateEffect();
		}
	}

	public virtual void ActivateEffect()
	{
	}
}
